function ReportPreview({ report, filters, outputFields }) {
  const toIso = (value) => {
    const [day, month, year] = value.split("/");
    return `${year}-${month}-${day}`;
  };
  const dateField = report.toLowerCase().includes("departure") ? "departureISO" : "arrivalISO";
  const rows = marketReservations.filter((record) => record[dateField] >= toIso(filters.from) && record[dateField] <= toIso(filters.to) && (filters.roomType === "All room types" || record.roomType === filters.roomType) && (filters.rateType === "All rate types" || record.rateType === filters.rateType) && (filters.businessSource === "All business sources" || record.source === filters.businessSource));
  const totalRevenue = rows.reduce((total, record) => total + Number(record.total.replace(/,/g, "")), 0);
  const averageStay = rows.length ? rows.reduce((total, record) => total + record.nights, 0) / rows.length : 0;
  const reportRows = rows.map(({ children: childCount, ...record }) => ({ ...record, childCount }));
  const columns = [
    { title: "Reservation", dataIndex: "id", width: 138 },
    { title: "Guest", dataIndex: "guest" },
    { title: "Arrival", dataIndex: "arrival", width: 78 },
    { title: "Departure", dataIndex: "departure", width: 86 },
    { title: "Room", dataIndex: "room", width: 64 },
    { title: "Room type", dataIndex: "roomType" },
    { title: "Rate type", dataIndex: "rateType" },
    { title: "Source", dataIndex: "source", width: 118 },
    { title: "Total", dataIndex: "total", width: 104, align: "right", render: (value) => `SAR ${value}` }
  ];
  return <div className="report-preview"><div className="report-preview-summary"><MiniMetric label="Matching stays" value={String(rows.length).padStart(2, "0")} detail={`${filters.from} to ${filters.to}`} tone="blue" /><MiniMetric label="Gross revenue" value={`SAR ${totalRevenue.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`} detail="Selected reservation rows" tone="yellow" /><MiniMetric label="Average stay" value={`${averageStay.toFixed(1)} nights`} detail={`${outputFields.length} output fields selected`} tone="purple" /></div><div className="report-preview-note"><Info size={15} />Operational values are standardized in English across {marketSummary.sourceRowsReviewed} property records.</div><WorkspaceTable columns={columns} rows={reportRows.slice(0, 24)} rowKey="id" /></div>;
}

export function ReportsView() {
  const [activeGroup, setActiveGroup] = useState("Reservation Report");
  const [activeReport, setActiveReport] = useState("Arrival List");
  const [reportSearch, setReportSearch] = useState("");
  const [favouritesOnly, setFavouritesOnly] = useState(false);
  const [filters, setFilters] = useState(initialReportFilters);
  const [outputFields, setOutputFields] = useState(["Arrival date", "Room type", "Business source"]);
  const [generated, setGenerated] = useState(false);
  const [notice, setNotice] = useState("Select a report and configure its filters and output.");
  const currentGroup = reportGroups.find((group) => group.name === activeGroup);
  const arrivalList = activeReport === "Arrival List";
  const visibleGroups = reportGroups.map((group) => ({ ...group, reports: group.reports.filter((report) => report.toLowerCase().includes(reportSearch.toLowerCase())) })).filter((group) => !reportSearch || group.name.toLowerCase().includes(reportSearch.toLowerCase()) || group.reports.length);
  const updateFilter = (field, value) => setFilters((current) => ({ ...current, [field]: value }));
  const chooseGroup = (group) => { setActiveGroup(group.name); setActiveReport(group.reports[0] || ""); setGenerated(false); setNotice(`${group.name} opened for review.`); };
  const chooseReport = (report) => { setActiveReport(report); setGenerated(false); setNotice(`${report} selected. Configure filters to prepare the report.`); };
  const resetPreview = () => { setFilters(initialReportFilters); setOutputFields(["Arrival date", "Room type", "Business source"]); setGenerated(false); setNotice(`${activeReport || activeGroup} filters reset.`); };
  const toggleOutput = (field) => setOutputFields((current) => current.includes(field) ? current.filter((item) => item !== field) : [...current, field]);

  return <section className="reports-view"><aside className="report-catalog"><div className="report-catalog-header"><span>Reports</span><b>Catalogue</b></div><Input allowClear aria-label="Search reports" onChange={(event) => setReportSearch(event.target.value)} placeholder="Search reports" prefix={<Search size={14} />} value={reportSearch} /><Checkbox checked={favouritesOnly} onChange={(event) => { setFavouritesOnly(event.target.checked); setNotice(`Favourite reports ${event.target.checked ? "shown" : "hidden"}.`); }}>Favourites only</Checkbox><div className="report-catalog-list">{visibleGroups.map((group) => <div key={group.name}><button aria-expanded={activeGroup === group.name} className={activeGroup === group.name ? "active-report-group" : ""} onClick={() => chooseGroup(group)}><FileText size={15} />{group.name}<ChevronRight size={14} /></button>{activeGroup === group.name && <div>{group.reports.length ? group.reports.map((report) => <button className={activeReport === report ? "active" : ""} key={report} onClick={() => chooseReport(report)}>{report}</button>) : <p>Select a report family to review available reports.</p>}</div>}</div>)}</div></aside><main className="report-canvas"><div className="report-heading"><div><span>{activeGroup}</span><h2>{activeReport || "Graphs and Charts"}</h2><p>{activeReport ? "Configure the report using the selected property and business date." : "Choose a report from the catalogue to configure its filters and output."}</p></div><div className="report-heading-actions"><Button onClick={resetPreview} size="small">Reset</Button><Button disabled={!generated || !activeReport} icon={<Download size={14} />} onClick={() => setNotice(`${activeReport} export package prepared for review.`)} size="small">Export</Button></div></div>{activeReport ? <><div className="report-scope-bar"><span><FileText size={14} />Operational report form · selected property</span><span>Business date: 09 Jul 2026</span></div><div className="report-filter-sheet"><div className="report-filter-title"><div><b>{arrivalList ? "Arrival List configuration" : "Report configuration"}</b><span>{arrivalList ? "Controls for the selected report and business date." : "Uses the Arrival List structure for the selected business date."}</span></div><Button className="primary-command" icon={<BarChart3 size={14} />} onClick={() => { setGenerated(true); setNotice(`${activeReport} report view prepared for review.`); }} size="small">Report</Button></div><div className="report-filter-grid"><label>Arrival from<PmsDatePicker aria-label="Report arrival from" onChange={(value) => updateFilter("from", value)} value={filters.from} /></label><label>Arrival to<PmsDatePicker aria-label="Report arrival to" onChange={(value) => updateFilter("to", value)} value={filters.to} /></label><label>Company<Input aria-label="Report company" onChange={(event) => updateFilter("company", event.target.value)} placeholder="All companies" value={filters.company} /></label><label>Room type<Select aria-label="Report room type" onChange={(value) => updateFilter("roomType", value)} options={[{ value: "All room types", label: "All room types" }, { value: "Superior King Room", label: "Superior King Room" }, { value: "Superior Twin Room", label: "Superior Twin Room" }, { value: "Junior Suite", label: "Junior Suite" }, { value: "Executive Suite", label: "Executive Suite" }]} value={filters.roomType} /></label><label>Travel agent<Input aria-label="Report travel agent" onChange={(event) => updateFilter("travelAgent", event.target.value)} placeholder="All travel agents" value={filters.travelAgent} /></label><label>Rate type<Select aria-label="Report rate type" onChange={(value) => updateFilter("rateType", value)} options={[{ value: "All rate types", label: "All rate types" }, { value: "Room Only Flexible", label: "Room Only Flexible" }, { value: "Room Only Non-Refundable", label: "Room Only Non-Refundable" }]} value={filters.rateType} /></label><label>Business source<Select aria-label="Report business source" onChange={(value) => updateFilter("businessSource", value)} options={[{ value: "All business sources", label: "All business sources" }, { value: "Direct", label: "Direct" }, { value: "Corporate", label: "Corporate" }, { value: "Travel Agent", label: "Travel Agent" }]} value={filters.businessSource} /></label><label>Amount interpretation<Select aria-label="Report amount interpretation" onChange={(value) => updateFilter("amount", value)} options={[{ value: "Any amount", label: "Any amount" }, { value: "Gross amount", label: "Gross amount" }, { value: "Net amount", label: "Net amount" }]} value={filters.amount} /></label><label>Market segment<Input aria-label="Report market segment" onChange={(event) => updateFilter("marketSegment", event.target.value)} placeholder="All market segments" value={filters.marketSegment} /></label><label>Rate range<Input aria-label="Report rate range" onChange={(event) => updateFilter("rateRange", event.target.value)} placeholder="Any rate range" value={filters.rateRange} /></label><label>User<Input aria-label="Report user" onChange={(event) => updateFilter("user", event.target.value)} placeholder="All users" value={filters.user} /></label><label>Reservation guarantee<Select aria-label="Report reservation guarantee" onChange={(value) => updateFilter("guarantee", value)} options={[{ value: "All guarantees", label: "All guarantees" }, { value: "Guaranteed", label: "Guaranteed" }, { value: "Not guaranteed", label: "Not guaranteed" }]} value={filters.guarantee} /></label><label className="report-remarks">Remarks<Input aria-label="Report remarks" onChange={(event) => updateFilter("remarks", event.target.value)} placeholder="Optional property filter" value={filters.remarks} /></label></div><div className="report-output-fields"><div><b>Selectable output columns</b><span>Choose the fields shown in the report output.</span></div><div>{reportOutputFields.map((field) => <Checkbox checked={outputFields.includes(field)} key={field} onChange={() => toggleOutput(field)}>{field}</Checkbox>)}</div></div></div>{generated ? <ReportPreview filters={filters} outputFields={outputFields} report={activeReport} /> : <div className="report-empty"><BarChart3 size={28} /><strong>Ready to generate report</strong><span>Set filters and output columns, then select Report to generate the property view.</span></div>}</> : <div className="report-empty source-gap"><FileText size={28} /><strong>Catalogue family ready for review</strong><span>Select a report family to configure its available filters and output.</span></div>}<div className="surface-status"><CheckCircle2 size={14} />{notice}</div></main></section>;
}

